raw_1e = bytes.fromhex("")
xor_all = bytes([b ^ 0xff for b in raw_1e])
print("Non-zero bytes in XOR(all):")
[print("  [%3d] 0x%02x (%3d)" % (i, b, b)) for i, b in enumerate(xor_all) if b > 0]
